if mibBuilder.loadTexts: ds0IfIndex.setDescription('This attribute defines the index for this table.\n        This is derived from the following formula:\n\t  index = 31 * (Ds1# - 1) + ds0#\n           \n         where : Ds1# - The T1/E1 line number in the range 1 - 8.\n                 ds0# - The ds0 channel number ranging from\n                        1 to 24 for T1\n                    and 1 to 31 for E1.')
