if mibBuilder.loadTexts: ds0RobbedBitSignalling.setDescription('This object indicates if Robbed Bit Signalling is\n               turned on or off for a given ds0.  This only\n               applies to DS0s on a DS1 link.  For E1 links the\n               value is always off (false). For T1 links, the default \n               value is true if the line is configured for CAS signaling,\n               the default value is false if the line is configured for\n               CCS signaling or no signaling.')
ds0IdleCode = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 7, 1, 1, 3), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 15)).clone(0)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: ds0IdleCode.setStatus('current')
if mibBuilder.loadTexts: ds0IdleCode.setDescription('This object contains the code transmitted in the\n         ABCD bits when the ds0 is not connected and\n         ds0TransmitCodesEnable is enabled.  The object is\n         a bitmap and the various bit positions are:\n              Bit 0 (value 1)     D bit\n              Bit 1 (value 2)     C bit\n              Bit 2 (value 4)     B bit\n              Bit 3 (value 8)     A bit\n\t This object is useful for ds0 conditioning to be\n\t done if an alarm condition is detected from the\n\t network side. DS0 conditioning is implemented in\n\t the trunking application only.\n\n\t This object is not applicable in the CAS backhaul \n         application.\n\n         From vism 2.0.3 release onwards this object can\n         be configured in any mode, but will be applicable\n         only in trunking application and will be ignored\n         in other applications.')
ds0SeizedCode = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 7, 1, 1, 4), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 15)).clone(15)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: ds0SeizedCode.setStatus('current')
if mibBuilder.loadTexts: ds0SeizedCode.setDescription('This object contains the code transmitted in the\n        ABCD bits when the ds0 is connected and\n        ds0TransmitCodesEnable is enabled.  The object is\n        a bitmap and the various bit positions are:\n           Bit 0 (value 1)     D bit\n           Bit 1 (value 2)     C bit\n           Bit 2 (value 4)     B bit\n           Bit 3 (value 8)     A bit\n\tThis object is useful for ds0 conditioning to be\n\tdone if an alarm condition is detected from the\n\tnetwork side. DS0 conditioning is implemented in\n        the trunking application only.\n\n        This object is not applicable in the CAS backhaul\n\tapplication.\n\n        From vism 2.0.3 release onwards this object can\n        be configured in any mode, but will be applicable\n        only in trunking application and will be ignored\n        in other applications.')
ds0ReceivedCode = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 7, 1, 1, 5), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 15))).setMaxAccess("readonly")
