if mibBuilder.loadTexts: ds0ReceivedCode.setDescription('This object contains the code being received in\n               the ABCD bits.  The object is a bitmap and the\n               various bit positions are:\n                     Bit 0 (value 1)    D bit\n                     Bit 1 (value 2)    C bit\n                     Bit 2 (value 4)    B bit\n                     Bit 3 (value 8)    A bit')
